begin;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) select ('a3100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'invoice-'||n||'@example.test','{"name":"Invoice fixture"}',now() from generate_series(1,6) n;
delete from public.role_assignments where user_id in ('a3100000-0000-4000-8000-000000000001','a3100000-0000-4000-8000-000000000003','a3100000-0000-4000-8000-000000000004','a3100000-0000-4000-8000-000000000005','a3100000-0000-4000-8000-000000000006');
insert into public.role_assignments values('a3100000-0000-4000-8000-000000000001','super_admin'),('a3100000-0000-4000-8000-000000000003','branch'),('a3100000-0000-4000-8000-000000000004','coach'),('a3100000-0000-4000-8000-000000000005','sales'),('a3100000-0000-4000-8000-000000000006','admin');
insert into public.branches(id,slug,name,provisional) values('a3200000-0000-4000-8000-000000000001','invoice-one','Invoice one',false),('a3200000-0000-4000-8000-000000000002','invoice-two','Invoice two',false);
insert into public.branch_sports values('a3200000-0000-4000-8000-000000000001','swimming'),('a3200000-0000-4000-8000-000000000002','swimming');
insert into public.branch_permissions select ('a3100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'a3200000-0000-4000-8000-000000000001' from generate_series(3,5) n;
insert into public.families(id,name) values('a3300000-0000-4000-8000-000000000001','Invoice family'),('a3300000-0000-4000-8000-000000000002','Unrelated family');
insert into public.guardians values('a3300000-0000-4000-8000-000000000001','a3100000-0000-4000-8000-000000000002');
insert into public.family_branches values('a3300000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001');
insert into public.children(id,family_id,name,reported_age) values('a3400000-0000-4000-8000-000000000001','a3300000-0000-4000-8000-000000000001','Invoice child one',6),('a3400000-0000-4000-8000-000000000002','a3300000-0000-4000-8000-000000000001','Invoice child two',8),('a3400000-0000-4000-8000-000000000003','a3300000-0000-4000-8000-000000000002','Unrelated child',8);
insert into public.child_sports(child_id,sport) select id,'swimming' from public.children where id in ('a3400000-0000-4000-8000-000000000001','a3400000-0000-4000-8000-000000000002','a3400000-0000-4000-8000-000000000003');
insert into public.commercial_packages(id,branch_id,sport,name,price_minor,session_allowance,terms,created_by) values('a3500000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001','swimming','Synthetic package one',12505,4,'Explicit synthetic price only','a3100000-0000-4000-8000-000000000001'),('a3500000-0000-4000-8000-000000000002','a3200000-0000-4000-8000-000000000002','swimming','Synthetic other branch',10000,4,'Explicit synthetic price only','a3100000-0000-4000-8000-000000000001');
create function pg_temp.invoice_data() returns jsonb language sql as $$select '{"family_id":"a3300000-0000-4000-8000-000000000001","branch_id":"a3200000-0000-4000-8000-000000000001","reference":"SYNTHETIC-INVOICE-001","lines":[{"child_id":"a3400000-0000-4000-8000-000000000001","package_id":"a3500000-0000-4000-8000-000000000001","quantity":2},{"child_id":"a3400000-0000-4000-8000-000000000002","package_id":"a3500000-0000-4000-8000-000000000001","quantity":1}]}'::jsonb$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data(),gen_random_uuid())$$,'42501',null,'Branch has no implicit invoice authority');
reset role;
insert into public.product_permissions(user_id,branch_id,permission) values('a3100000-0000-4000-8000-000000000003','a3200000-0000-4000-8000-000000000001','finance.payment');
set local role authenticated;
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data(),gen_random_uuid())$$,'42501',null,'Payment authority does not grant invoice authoring');
reset role;
insert into public.product_permissions(user_id,branch_id,permission) select ('a3100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'a3200000-0000-4000-8000-000000000001','finance.invoices' from generate_series(3,5) n;
insert into public.product_permissions(user_id,branch_id,permission) values('a3100000-0000-4000-8000-000000000003','a3200000-0000-4000-8000-000000000001','finance.view');
set local role authenticated;
select lives_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data(),'a3600000-0000-4000-8000-000000000001')$$,'Explicit invoice author creates two child/package lines atomically');
select lives_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data(),'a3600000-0000-4000-8000-000000000001')$$,'Same request retry succeeds without duplicate invoice');
select is((select count(*)::int from public.commercial_invoices where family_id='a3300000-0000-4000-8000-000000000001'),1,'Retry leaves one invoice');
select set_config('test.invoice',coalesce((select id::text from public.commercial_invoices where family_id='a3300000-0000-4000-8000-000000000001' limit 1),'00000000-0000-4000-8000-000000000000'),true);
select is((select count(*)::int from public.commercial_invoice_lines where invoice_id=current_setting('test.invoice')::uuid),2,'Both immutable line snapshots are present');
select is((select sum(quantity::bigint*unit_minor)::bigint from public.commercial_invoice_lines where invoice_id=current_setting('test.invoice')::uuid),37515::bigint,'Exact AED minor-unit total derives from package prices');
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data(),gen_random_uuid())$$,'P0409',null,'Unique branch invoice reference rejects a second submission with a fresh key');
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines,0,quantity}','3'),'a3600000-0000-4000-8000-000000000001')$$,'P0409',null,'Same key with changed invoice payload is rejected');
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines,1,child_id}','"a3400000-0000-4000-8000-000000000003"')||'{"reference":"FOREIGN-CHILD"}',gen_random_uuid())$$,'42501',null,'A known child UUID outside invoice family is denied');
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines,1,package_id}','"a3500000-0000-4000-8000-000000000002"')||'{"reference":"OTHER-BRANCH"}',gen_random_uuid())$$,'42501',null,'Line package must belong to exact invoice branch');
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines,0,unit_minor}','1')||'{"reference":"FORGED-PRICE"}',gen_random_uuid())$$,'22023',null,'Direct RPC cannot supply a lower unit price');
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines}','[]')||'{"reference":"EMPTY-INV"}',gen_random_uuid())$$,'22023',null,'Empty invoice is rejected');
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines,0,quantity}','1.5')||'{"reference":"FRACTIONAL"}',gen_random_uuid())$$,'22023',null,'Fractional quantities cannot enter exact-money ledger');
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines,1}',pg_temp.invoice_data()->'lines'->0)||'{"reference":"DUP-LINE"}',gen_random_uuid())$$,'22023',null,'Repeated child/package lines must use one quantity');
select is((select count(*)::int from public.commercial_invoices where family_id='a3300000-0000-4000-8000-000000000001'),1,'Invalid second lines leave no partial invoice');
select throws_ok($$select public.product_command('commercial.invoice.adjust',jsonb_build_object('invoice_id',current_setting('test.invoice'),'kind','discount','amount_minor',1,'reason','Unapproved invoice discount'),gen_random_uuid())$$,'42501',null,'Invoice authoring does not imply discount approval');
select lives_ok($$select public.product_command('commercial.payment.record',jsonb_build_object('family_id','a3300000-0000-4000-8000-000000000001','branch_id','a3200000-0000-4000-8000-000000000001','invoice_id',current_setting('test.invoice'),'amount_minor',37515,'method','cash','reference','SYNTHETIC-INVOICE-PAID'),gen_random_uuid())$$,'Existing offline payment flow pays a standalone invoice');
select is((select sum(amount_minor)::bigint from public.commercial_allocations where invoice_id=current_setting('test.invoice')::uuid),37515::bigint,'Standalone invoice uses the existing allocation ledger');
reset role;
select is((select count(*)::int from public.commercial_memberships where family_id='a3300000-0000-4000-8000-000000000001'),0,'Posting or paying invoice creates no membership or terms acceptance');
select throws_ok($$update public.commercial_invoice_lines set unit_minor=1 where invoice_id=current_setting('test.invoice')::uuid$$,'42501',null,'Posted line amount is immutable even to owner');
select throws_ok($$delete from public.commercial_invoices where id=current_setting('test.invoice')::uuid$$,'42501',null,'Posted invoice is immutable even to owner');
delete from public.family_branches where family_id='a3300000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data(),'a3600000-0000-4000-8000-000000000001')$$,'42501',null,'Removing exact family branch link invalidates a cached write replay');
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"UNLINKED"}',gen_random_uuid())$$,'42501',null,'Current family branch link is required for every invoice');
select is((select count(*)::int from public.commercial_invoices where family_id='a3300000-0000-4000-8000-000000000001'),0,'Removing family link removes financial record visibility');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.commercial_invoices where family_id='a3300000-0000-4000-8000-000000000001'),1,'Parent can read own standalone invoice');
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"PARENT"}',gen_random_uuid())$$,'42501',null,'Parent cannot author invoice');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"COACH"}',gen_random_uuid())$$,'42501',null,'Coach is excluded even with an accidental invoice grant');
select is((select count(*)::int from public.commercial_invoices),0,'Coach cannot see financial invoices');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"SALES"}',gen_random_uuid())$$,'42501',null,'Sales is excluded even with an accidental invoice grant');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"HEAD-UNGRANTED"}',gen_random_uuid())$$,'42501',null,'Head Office does not inherit invoice authoring');
reset role;
select ok((select membership_id is null and author_reference='SYNTHETIC-INVOICE-001' from public.commercial_invoices where id=current_setting('test.invoice')::uuid),'Standalone invoice has its own author reference and no fabricated membership');
select is((select count(*)::int from public.commercial_invoice_lines where invoice_id=current_setting('test.invoice')::uuid and child_id is not null and package_id='a3500000-0000-4000-8000-000000000001' and description_ar<>'' and line_position in (1,2)),2,'Lines preserve child, package, Arabic description and order snapshots');
insert into public.family_branches values('a3300000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001');
update public.commercial_packages set active=false where id='a3500000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"INACTIVE-PACKAGE"}',gen_random_uuid())$$,'P0409',null,'Inactive package cannot be invoiced');
reset role;
update public.commercial_packages set active=true where id='a3500000-0000-4000-8000-000000000001';
update public.branches set active=false where id='a3200000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"INACTIVE-BRANCH"}',gen_random_uuid())$$,'P0409',null,'Inactive branch cannot issue a new invoice');
reset role;
update public.branches set active=true,provisional=true where id='a3200000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"PROVISIONAL-BRANCH"}',gen_random_uuid())$$,'P0409',null,'Provisional branch cannot issue a new invoice');
reset role;
update public.branches set provisional=false where id='a3200000-0000-4000-8000-000000000001';
delete from public.branch_sports where branch_id='a3200000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"WITHDRAWN-SPORT"}',gen_random_uuid())$$,'P0409',null,'Withdrawn branch sport cannot be invoiced');
reset role;
insert into public.branch_sports values('a3200000-0000-4000-8000-000000000001','swimming');
delete from public.child_sports where child_id='a3400000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"WRONG-CHILD-SPORT"}',gen_random_uuid())$$,'P0409',null,'Every child line must match a currently configured child sport');
reset role;
insert into public.child_sports(child_id,sport) values('a3400000-0000-4000-8000-000000000002','swimming');
insert into public.commercial_packages(id,branch_id,sport,name,price_minor,session_allowance,terms,created_by) values('a3500000-0000-4000-8000-000000000003','a3200000-0000-4000-8000-000000000001','swimming','Synthetic upper-bound fixture',1000000000,4,'Explicit synthetic bound test only','a3100000-0000-4000-8000-000000000001');
set local role authenticated;
select throws_ok($$select public.product_command('commercial.invoice.create',jsonb_set(pg_temp.invoice_data(),'{lines,0,package_id}','"a3500000-0000-4000-8000-000000000003"')||'{"reference":"OVER-TOTAL"}',gen_random_uuid())$$,'22023',null,'Multiplication and full invoice total are bounded in exact minor units');
select throws_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||jsonb_build_object('reference','TOO-MANY-LINES','lines',(select jsonb_agg(pg_temp.invoice_data()->'lines'->0) from generate_series(1,21))),gen_random_uuid())$$,'22023',null,'Server rejects more than20lines before inserting');
select throws_ok($$insert into public.commercial_invoice_lines(invoice_id,description,quantity,unit_minor) values(current_setting('test.invoice')::uuid,'Injected line',1,1)$$,'42501',null,'Authenticated clients cannot append a line outside invoice command');
select throws_ok($$select private.commercial_command('commercial.invoice.create',pg_temp.invoice_data())$$,'42501',null,'Internal invoice dispatcher remains private');
select is((select count(*)::int from public.commercial_invoices where family_id='a3300000-0000-4000-8000-000000000001'),1,'Every rejected catalogue and amount change rolls back all invoice writes');
reset role;
insert into public.product_permissions(user_id,permission) values('a3100000-0000-4000-8000-000000000006','finance.invoices');
delete from public.family_branches where family_id='a3300000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.product_command('commercial.invoice.create',pg_temp.invoice_data()||'{"reference":"HEAD-EXPLICIT"}',gen_random_uuid())$$,'Explicitly authorized Head Office retains organization-wide family invoicing');
reset role;
select * from finish();
rollback;
